H = "Hakeem Force Academy"
QS = [
(H, "What is the value of sin 0 degrees?", ["1", "0", "-1", "1/2"], 1, "On the unit circle the angle 0 degrees points along the x-axis, where the y-coordinate (sine) is 0.", "Cos 0 degrees is 1 and sin 90 degrees is 1.", [2725, 2727]),
(H, "How many straight lines can pass through a single given point?", ["Only one", "Exactly two", "Infinitely many", "None"], 2, "Through one point we can draw a line in every possible direction, so there are infinitely many lines.", "Exactly one straight line passes through two different points.", [181]),
(H, "Ali is 10 years old and he is twice as old as his sister. How old will his sister be after 20 years?", ["15", "25", "30", "20"], 1, "His sister is 10 divided by 2 = 5 years old now. After 20 years she will be 5 + 20 = 25.", "The age difference between two people never changes with time.", [1390]),
(H, "Ali is 5 years old and his sister is 8 years old. When Ali is 10 years old, how old will his sister be?", ["15", "10", "13", "18"], 2, "The age difference is 8 - 5 = 3 years. When Ali is 10, his sister is 10 + 3 = 13.", "The sister is always 3 years older than Ali.", [1877]),
(H, "If my mother is your sister, what am I to you?", ["Cousin", "Nephew or niece", "Uncle", "Brother"], 1, "Your sister is my mother, so I am her child, which makes me your sister's child, that is your nephew or niece.", "The child of your brother is also your nephew or niece.", [1887]),
(H, "Your age is 3 years and your sister is twice your age. What will be your sister's age when you are 23 years old?", ["46", "26", "29", "23"], 1, "Your sister is 3 x 2 = 6 now, so she is 3 years older. When you are 23 she will be 23 + 3 = 26.", "Age difference stays constant, so add it to the younger person's age.", [751]),
(H, "According to the Quran, whom should a person respect and obey most (after Allah)?", ["Neighbours", "Parents", "Relatives", "Brothers and sisters"], 1, "The Quran commands good treatment of parents right after the command to worship Allah alone, and tells us not even to say 'uff' to them.", "Surah Bani Israil (verses 23 to 24) gives the command about kindness to parents.", [1357]),
(H, "Fill in the blank: I go to sleep ____ I am tired.", ["while", "when", "until", "unless"], 1, "'When' shows the time at which something happens, so 'I go to sleep when I am tired' is correct.", "'Whenever' can also be used here to mean every time.", [1572]),
(H, "Fill in the blank: ____ you were sleeping, the telephone rang.", ["Since", "Until", "While", "During"], 2, "'While' joins two actions that happen at the same time, and here it links a clause with a subject and verb.", "'During' is followed by a noun, not by a clause like 'you were sleeping'.", [1523, 1561, 1562]),
(H, "What is the antonym of 'sloppy'?", ["Careless", "Messy", "Neat", "Lazy"], 2, "Sloppy means careless or untidy, so its opposite is neat or careful.", "Another opposite of sloppy is meticulous.", [930]),
(H, "What is a synonym of 'sloppy'?", ["Careless", "Tidy", "Precise", "Elegant"], 0, "Sloppy means done without care or attention, which is the same as careless.", "Slovenly and untidy are also close in meaning to sloppy.", [1035]),
(H, "Which is the smallest Muslim country of the world by area?", ["Brunei", "Bahrain", "Kuwait", "Maldives"], 3, "The Maldives covers only about 300 square kilometres, less than Bahrain (about 780) and Brunei (about 5,770).", "The Maldives is also the smallest country in Asia.", [3829]),
(H, "Which is the smallest of the five rivers of Punjab (Pakistan) in length?", ["Chenab", "Jhelum", "Sutlej", "Ravi"], 3, "The Ravi is about 720 km long, the shortest of the five rivers, and is commonly called the smallest river of Pakistan in textbooks.", "The Jhelum is only slightly longer, at about 725 km, so some sources give slightly different rankings.", [154]),
(H, "Fill in the blank: He did not approve ____ smoking.", ["to", "of", "for", "with"], 1, "The verb 'approve' takes the preposition 'of', as in 'approve of something'.", "'Disapprove of' is used in the same way.", [1524, 1582]),
(H, "Father is to son as mother is to ____.", ["Sister", "Daughter", "Aunt", "Wife"], 1, "A father and his male child are father and son. In the same way a mother and her female child are mother and daughter.", "Analogy questions test the same relationship in both pairs.", [1557]),
(H, "Which of the following was a son of the Holy Prophet Muhammad (PBUH)?", ["Hasan", "Husain", "Qasim", "Ali"], 2, "Hazrat Qasim (RA) was the first son of the Prophet (PBUH) and Hazrat Khadija (RA); he died as a small child.", "Hasan and Husain were the grandsons of the Prophet (PBUH).", [4427]),
(H, "On which side of Pakistan does China lie?", ["North", "South", "West", "East"], 0, "Pakistan's northern border, through Gilgit-Baltistan, meets China's Xinjiang region.", "The Khunjerab Pass connects Pakistan with China.", [2331]),
(H, "Choose the correct word: The Arabian Sea is ____ in the southern part of Pakistan.", ["being situated", "situating", "situated", "to situate"], 2, "The sentence needs the past participle 'situated' after 'is' to mean 'located'.", "'Is situated' is a passive form often used to describe locations.", [2408]),
(H, "Select the correct spelling.", ["Divercity", "Diversity", "Diversety", "Divirsity"], 1, "The word is spelled d-i-v-e-r-s-i-t-y, from the Latin word diversus.", "Its opposite is uniformity.", [2386]),
(H, "Which is the correct spelling of the word?", ["Begining", "Beginning", "Beggining", "Beginnig"], 1, "The verb 'begin' ends in a single stressed vowel and consonant, so the n is doubled before -ing: beginning.", "The same rule gives running, stopping and getting.", [517]),
]
